package ru.mcsa.bukkit;
import org.bukkit.Material;import java.util.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.*;import org.bukkit.enchantments.Enchantment;import net.kyori.adventure.text.Component;
public class ItemMetadata implements ItemMeta {
 private Long opaqueToken;private Long nativeToken;private Component name;private List<Component> lore;protected org.bukkit.potion.PotionType potion;protected int damage;protected Integer maxDamage;private DataContainer pdc=new DataContainer();private final Map<Enchantment,Integer> enchants=new LinkedHashMap<>();protected final Map<Enchantment,Integer> stored=new LinkedHashMap<>();private final Set<ItemFlag> flags=new LinkedHashSet<>();private final Material material;
 private ItemMetadata(Material material){this.material=material;}
 private static final class Wear extends ItemMetadata implements Damageable {Wear(Material m){super(m);}public int getDamage(){return damage;}public void setDamage(int value){if(value<0)throw new IllegalArgumentException("Отрицательный износ");damage=value;}public boolean hasMaxDamage(){return maxDamage!=null;}public int getMaxDamage(){if(maxDamage==null)throw new IllegalStateException("Максимальная прочность не задана");return maxDamage;}public void setMaxDamage(Integer value){if(value!=null&&value<=0)throw new IllegalArgumentException("Прочность должна быть положительной");maxDamage=value;}}
 private static final class Stored extends ItemMetadata implements EnchantmentStorageMeta {Stored(Material m){super(m);}public Map<Enchantment,Integer> getStoredEnchants(){return Collections.unmodifiableMap(new LinkedHashMap<>(stored));}}
 private static final class Potion extends ItemMetadata implements PotionMeta {Potion(Material m){super(m);}public org.bukkit.potion.PotionType getBasePotionType(){return potion;}public void setBasePotionType(org.bukkit.potion.PotionType type){potion=type;}}
 public static ItemMetadata create(Material material){return java.util.List.of(Material.POTION,Material.SPLASH_POTION,Material.LINGERING_POTION,Material.TIPPED_ARROW).contains(material)?new Potion(material):material==Material.ENCHANTED_BOOK?new Stored(material):material.getMaxDurability()>0?new Wear(material):new ItemMetadata(material);}
 public void displayName(Component value){name=value;}public Component displayName(){return name;}public void lore(List<? extends Component> value){lore=value==null?null:new ArrayList<>(value);}public List<Component> lore(){return lore==null?null:new ArrayList<>(lore);}
 public DataContainer getPersistentDataContainer(){return pdc;}
 public boolean addEnchant(Enchantment enchant,int level,boolean ignore){Objects.requireNonNull(enchant);if(level<1||(!ignore&&level>enchant.getMaxLevel()))return false;Integer old=enchants.put(enchant,level);return old==null||old!=level;}
 public Map<Enchantment,Integer> getEnchants(){return Collections.unmodifiableMap(new LinkedHashMap<>(enchants));}public void addItemFlags(ItemFlag... value){flags.addAll(Arrays.asList(value));}public Set<ItemFlag> getItemFlags(){return Collections.unmodifiableSet(new LinkedHashSet<>(flags));}
 public ItemMetadata clone(){return copyFor(material);}
 public ItemMetadata copyFor(Material target){ItemMetadata copy=create(target);copy.opaqueToken=opaqueToken;copy.nativeToken=nativeToken;copy.name=name;copy.lore=lore==null?null:new ArrayList<>(lore);copy.pdc=pdc.clone();copy.enchants.putAll(enchants);copy.stored.putAll(stored);copy.flags.addAll(flags);copy.potion=potion;copy.damage=damage;copy.maxDamage=maxDamage;return copy;}
 public String serialize(){Map<String,Object> out=new LinkedHashMap<>();if(potion!=null)out.put("potion",potion.getKey().toString());if(nativeToken!=null)out.put("_native",nativeToken);if(opaqueToken!=null)out.put("_opaque",opaqueToken);if(name!=null)out.put("name",Yaml.parse(Text.json(name)));if(lore!=null){List<Object> lines=new ArrayList<>();for(Component c:lore)lines.add(Yaml.parse(Text.json(c)));out.put("lore",lines);}if(!pdc.isEmpty())out.put("pdc",Yaml.parse(pdc.serialize()));if(damage!=0)out.put("damage",damage);if(maxDamage!=null)out.put("maxDamage",maxDamage);if(!enchants.isEmpty())out.put("enchants",enchantMap(enchants));if(!stored.isEmpty())out.put("stored",enchantMap(stored));if(!flags.isEmpty()){List<String> names=new ArrayList<>();for(ItemFlag flag:flags)names.add(flag.name());out.put("flags",names);}return out.isEmpty()?"":Yaml.write(out);}
 private static Map<String,Object> enchantMap(Map<Enchantment,Integer> enchants){Map<String,Object> out=new LinkedHashMap<>();for(Map.Entry<Enchantment,Integer> e:enchants.entrySet())out.put(e.getKey().getKey().toString(),e.getValue());return out;}
 public static ItemMetadata parse(Material material,String text){ItemMetadata result=create(material);if(text.isEmpty())return result;Map<String,Object> map=Yaml.parse(text);if(map.get("potion") instanceof String)result.potion=org.bukkit.potion.PotionType.valueOf(Ascii.upper(((String)map.get("potion")).replace("minecraft:","")));if(map.get("_opaque") instanceof Number)result.opaqueToken=((Number)map.get("_opaque")).longValue();if(map.get("_native") instanceof Number)result.nativeToken=((Number)map.get("_native")).longValue();if(map.containsKey("name"))result.name=Text.fromJson(Yaml.write(map.get("name")));if(map.get("lore") instanceof List){result.lore=new ArrayList<>();for(Object c:(List<?>)map.get("lore"))result.lore.add(Text.fromJson(Yaml.write(c)));}if(map.containsKey("pdc"))result.pdc=DataContainer.parse(Yaml.write(map.get("pdc")));if(map.get("damage") instanceof Number)result.damage=((Number)map.get("damage")).intValue();if(map.get("maxDamage") instanceof Number)result.maxDamage=((Number)map.get("maxDamage")).intValue();for(String field:List.of("enchants","stored"))if(map.get(field) instanceof Map)for(Map.Entry<?,?> e:((Map<?,?>)map.get(field)).entrySet()){Enchantment enchant=Enchantment.getByKey(org.bukkit.NamespacedKey.fromString((String)e.getKey()));if(enchant!=null&&(e.getValue() instanceof Number))(field.equals("enchants")?result.enchants:result.stored).put(enchant,((Number)e.getValue()).intValue());}if(map.get("flags") instanceof List)for(Object value:(List<?>)map.get("flags"))result.flags.add(ItemFlag.valueOf((String)value));return result;}
 @Override public boolean equals(Object other){return other instanceof ItemMetadata&&normalized().equals(((ItemMetadata)other).normalized());}private Map<String,Object> normalized(){String text=serialize();Map<String,Object> map=text.isEmpty()?new LinkedHashMap<>():Yaml.parse(text);map.remove("_native");return map;}@Override public int hashCode(){return normalized().hashCode();}
}
